UPDATE tools SET
  best_for         = $d11h$פיתוח שיתופי בזמן אמת עם עורך מהיר במיוחד$d11h$,
  description      = $d11h$Zed הוא עורך קוד ביצועי גבוה שנכתב ב-Rust, עם שיתוף פעולה בזמן אמת ופונקציות AI. תוכנן למהירות ויעילות מקסימליות.$d11h$,
  description_long = $dl11h$Zed הוא עורך מודרני המעמיד את המהירות בראש סדר העדיפויות: נכתב ב-Rust, מציע ביצועים גבוהים משמעותית מ-VS Code בקבצים גדולים ופרויקטים מורכבים. שיתוף הפעולה בזמן אמת מאפשר למפתחים מרובים לערוך את אותו הקובץ בו-זמנית, כמו Google Docs אבל לקוד. משלב מודלי AI להשלמה אוטומטית, עם תמיכה נטיבית ב-macOS ו-Linux.$dl11h$,
  pros = ARRAY['ביצועים יוצאי דופן — נכתב ב-Rust', 'שיתוף פעולה בזמן אמת', 'AI משולב', 'ממשק נקי ומינימליסטי'],
  cons = ARRAY['זמין רק ל-macOS ו-Linux', 'מערכת אקולוגית מוגבלת של הרחבות', 'עקומת למידה למשתמשי VS Code']
WHERE slug = 'zed' AND lang = 'he';

UPDATE tools SET
